const http = require('http');
const { Server } = require('socket.io');
const { createAdapter } = require('@socket.io/redis-streams-adapter');
const { Redis } = require('ioredis');
const jwt = require('jsonwebtoken');
const { LegalContract } = require('../models/legalContract');

const server = http.createServer();
const io = new Server(server);

const redisClient = new Redis(process.env.REDIS_URL);
io.adapter(createAdapter(redisClient));

const contractNsp = io.of(/^\/legal\/contract-[a-zA-Z0-9]+$/);

contractNsp.use(async (socket, next) => {
  const token = socket.handshake.auth.token;
  if (!token) return next(new Error('Token missing'));

  try {
    const decoded = jwt.verify(token, process.env.LEGAL_PORTAL_SECRET);
    const contractId = socket.nsp.name.replace('/legal/contract-', '');

    // Validate that the attorney is explicitly listed as counsel for the contract
    const contract = await LegalContract.findById(contractId);
    if (!contract || !contract.authorizedAttorneyIds.includes(decoded.attorneyId)) {
      return next(new Error('Access denied: attorney not authorized on this contract'));
    }

    socket.attorney = decoded;
    next();
  } catch (err) {
    next(new Error('Authorization check failed'));
  }
});

contractNsp.on('connection', (socket) => {
  const contractId = socket.nsp.name.replace('/legal/contract-', '');

  socket.on('ot_delta_operation', (delta) => {
    socket.broadcast.emit('ot_delta_received', { contractId, delta });
  });
});

server.listen(4006);
